config.command:
set -eu
umask 077
export LC_ALL=C
base=/workspace/fieldkit
[ -d "$base" ] && [ ! -L "$base" ] || { printf 'Create the fieldkit folder in the sandbox workspace first.\n' >&2; exit 2; }
cd "$base"
need() {
  command -v "$1" >/dev/null 2>&1 || { printf 'Missing command: %s. Install the packages listed in this tool.\n' "$1" >&2; exit 127; }
}
check_file() {
  [ -f "$1" ] && [ ! -L "$1" ] || { printf 'Required regular file missing: %s\n' "$1" >&2; exit 2; }
  bytes=$(wc -c < "$1")
  [ "$bytes" -gt 0 ] && [ "$bytes" -le "$2" ] || { printf 'Input is empty or exceeds this tool size limit.\n' >&2; exit 2; }
}
need shellcheck
need shfmt
check_file input.sh 131072
printf 'SHELLCHECK\n'
status=0
shellcheck --shell=sh --format=gcc ./input.sh || status=$?
case "$status" in 0) printf 'No lint findings.\n' ;; 1) printf 'Lint findings need review.\n' ;; *) exit "$status" ;; esac
printf '\nFORMATTING DIFF\n'
status=0
shfmt -ln=posix -d ./input.sh || status=$?
case "$status" in 0) printf 'Formatting already consistent.\n' ;; 1) printf 'Formatting differences shown above; source unchanged.\n' ;; *) exit "$status" ;; esac
